import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  interpolateColors,
  delayRender,
  continueRender,
} from '../remotionShim';
// Library: none — native interpolate for smooth Apple-style inertia and UI transitions

if (typeof document !== "undefined") {
  const loadCustomFont = (family: string, url: string) => {
    const handle = delayRender(`Loading ${family}`);
    const format = url.endsWith(".otf") ? "opentype" : url.endsWith(".woff2") ? "woff2" : url.endsWith(".woff") ? "woff" : "truetype";
    const font = new FontFace(family, `url('${url}') format('${format}')`);
    font.load()
      .then(() => {
        document.fonts.add(font);
        continueRender(handle);
      })
      .catch((err) => {
        console.log(`Error loading ${family}`, err);
        continueRender(handle);
      });
  };
  // Load brand custom font
  loadCustomFont("Believe-Font", "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/brand_guidelines/fonts/6e3f2edcbb584480b2d9a1404eee140c.otf");
}



export type ComponentNameProps = Record<string, any>;

const FOLDER_LABELS = [
  "YouTube Videos", "Evan Videos", "Evan Uploaded", "YouTube Ideas", "Evan RAW", "Evan's Vlogs",
  "Evan Shorts", "Video Assets", "Editing Assets", "B-Roll Footage", "Sound FX", "Thumbnail PSDs",
  "Color Grades", "Music Library", "Sponsor Clips", "Voiceovers", "Script Drafts", "Export Masters",
  "Social Cuts", "Evan Archives", "Project Backups", "Render Cache", "Review Feedback", "Channel Art"
];

// Grid Layout Math for calculating specific coordinates
const getFolderCoords = (index: number) => {
  const col = index % 6;
  const row = Math.floor(index / 6);
  // Layout Math matching inside the container
  const x = 120 + col * 180;
  const y = 60 + row * 180;
  // Center of the folder item (180x180 box) relative to the 1600x900 canvas center (800, 450)
  // Sidebar is 280 wide. Folder Area starts at 280.
  // Folder absolute x in canvas: 280 + (x * s)
  // Relative to canvas center (800): x_rel = (280 + x + 90) - 800 = x - 430
  // Relative to canvas center (450): y_rel = (60 + y + 90) - 450 = y - 300
  return {
    x: (280 + x + 90) - 800,
    y: (60 + y + 90) - 450
  };
};

// Target Folder (index 0) absolute position on the 1600x900 grid:
// col = 0, row = 0 -> x = 120, y = 60
// Center of 180x180 folder relative to canvas center (800, 450):
// X: (280 + 120 + 90) - 800 = -310
// Y: (60 + 60 + 90) - 450 = -240
const TARGET_FOLDER_POS = getFolderCoords(0); // { x: -310, y: -240 }

// Helper to define smooth cursor/camera path (P3 now ends exactly on target folder)
const P0 = { x: -500, y: 350 };
const P1 = { x: -130, y: 120 };
const P2 = { x: 230, y: -240 };
const P3 = TARGET_FOLDER_POS; // Ends exactly on the center of the target folder

const getPathPos = (tf: number) => {
  const time = Math.max(0, Math.min(tf, 110));
  const e = Easing.inOut(Easing.quad);
  if (time < 15) return P0;
  if (time < 35) {
    const p = e((time - 15) / 20);
    return { x: P0.x + (P1.x - P0.x) * p, y: P0.y + (P1.y - P0.y) * p };
  }
  if (time < 45) return P1;
  if (time < 65) {
    const p = e((time - 45) / 20);
    return { x: P1.x + (P2.x - P1.x) * p, y: P1.y + (P2.y - P1.y) * p };
  }
  if (time < 75) return P2;
  if (time <= 110) {
    const p = e((time - 75) / 35);
    return { x: P2.x + (P3.x - P2.x) * p, y: P2.y + (P3.y - P2.y) * p };
  }
  return P3;
};

const SidebarSection: React.FC<{ title: string; items: string[]; isTags?: boolean; s: number; fontFamily: string }> = ({ title, items, isTags, s, fontFamily }) => (
  <div style={{ marginBottom: 24 * s, padding: `0 ${24 * s}px` }}>
    <div style={{ fontSize: 12 * s, color: '#666', fontWeight: 600, marginBottom: 12 * s, fontFamily }}>{title}</div>
    {items.map((item, i) => (
      <div key={i} style={{
        display: 'flex', alignItems: 'center', gap: 12 * s,
        padding: `${5 * s}px 0`, color: '#9CA3AF', fontSize: 14 * s,
        fontFamily
      }}>
        {isTags ? (
          <div style={{ width: 12 * s, height: 12 * s, borderRadius: '50%', backgroundColor: ['#FF5F56', '#FFBD2E', '#27C93F', '#AF52DE', '#FF9F0A'][i % 5] }} />
        ) : (
          <div style={{ width: 16 * s, height: 16 * s, border: `${1.5 * s}px solid #666`, borderRadius: 4 * s }} />
        )}
        {item}
      </div>
    ))}
  </div>
);

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 15,
  primaryColor = "#FEBF10",
  targetFolderText = "YouTube Videos",
  targetFolderTextFontFamily = "Believe-Font",
}) => {
  const frame = useCurrentFrame();
  const { width, height, durationInFrames } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Map the current frame into our accelerated choreography timeline (was 450, now 280 for snappier delivery)
  const t = (frame / Math.max(1, durationInFrames - 1)) * 280;

  // Cinematic camera logic
  const cursor = getPathPos(t);
  const camF = Math.max(0, t - 10);
  const cameraTarget = getPathPos(camF);

  const creepScale = interpolate(t, [110, 160], [2.8, 2.9], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const zoomProgress = interpolate(t, [160, 210], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.bezier(0.16, 1, 0.3, 1) });

  const finalCamX = interpolate(zoomProgress, [0, 1], [cameraTarget.x, 0]);
  const finalCamY = interpolate(zoomProgress, [0, 1], [cameraTarget.y, 0]);
  const scale = interpolate(zoomProgress, [0, 1], [creepScale, 1.0]);

  // Cursor states
  const cursorClickScale = interpolate(t, [158, 160, 165], [1, 0.8, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const cursorOpacity = interpolate(t, [170, 195], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });

  const getFolderScale = (index: number, time: number) => {
    if (index === 13) return 1 + 0.05 * interpolate(time, [25, 30, 40, 45], [0, 1, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    if (index === 3) return 1 + 0.05 * interpolate(time, [55, 60, 70, 75], [0, 1, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    if (index === 0) return 1 + 0.05 * interpolate(time, [100, 110], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
    return 1;
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: 'hidden' }}>
      
      {/* Abstract Glowing Background Elements */}
      <div style={{ position: 'absolute', width: '100%', height: '100%' }}>
        <div style={{
          position: 'absolute', width: 2500 * s, height: 2500 * s, left: -500 * s, top: -500 * s,
          background: `radial-gradient(circle at center, ${primaryColor}40 0%, ${primaryColor}10 30%, transparent 60%)`,
          opacity: interpolate(t, [160, 210], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
        }} />
        <div style={{
          position: 'absolute', width: 3000 * s, height: 3000 * s, right: -800 * s, bottom: -800 * s,
          background: `radial-gradient(circle at center, ${primaryColor}30 0%, ${primaryColor}05 40%, transparent 70%)`,
          opacity: interpolate(t, [160, 210], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }),
        }} />
      </div>

      {/* Cinematic Camera Container */}
      <div style={{
        position: 'absolute',
        width: 1600 * s,
        height: 900 * s,
        left: width / 2 - (1600 * s) / 2,
        top: height / 2 - (900 * s) / 2,
        transformOrigin: 'center',
        transform: `scale(${scale}) translate(${-finalCamX * s}px, ${-finalCamY * s}px)`,
        backgroundColor: '#161618',
        borderRadius: 16 * s,
        overflow: 'hidden',
        boxShadow: `0 ${30 * s}px ${100 * s}px rgba(0,0,0,0.6)`,
        border: `${1 * s}px solid rgba(255,255,255,0.08)`,
        willChange: 'transform'
      }}>
        
        {/* Top Bar */}
        <div style={{
          position: 'absolute', left: 0, top: 0, right: 0, height: 60 * s,
          display: 'flex', alignItems: 'center', padding: `0 ${24 * s}px`,
          borderBottom: `${1 * s}px solid rgba(255,255,255,0.05)`,
          backgroundColor: '#1E1E20',
          zIndex: 10
        }}>
          <div style={{ display: 'flex', gap: 8 * s, marginRight: 80 * s }}>
            <div style={{ width: 12 * s, height: 12 * s, borderRadius: '50%', backgroundColor: '#FF5F56' }} />
            <div style={{ width: 12 * s, height: 12 * s, borderRadius: '50%', backgroundColor: '#FFBD2E' }} />
            <div style={{ width: 12 * s, height: 12 * s, borderRadius: '50%', backgroundColor: '#27C93F' }} />
          </div>
          <div style={{ display: 'flex', gap: 12 * s, color: '#888', fontFamily: targetFolderTextFontFamily, fontSize: 18 * s }}>
            <div style={{ width: 28 * s, height: 28 * s, borderRadius: 6 * s, backgroundColor: 'rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{'<'}</div>
            <div style={{ width: 28 * s, height: 28 * s, borderRadius: 6 * s, backgroundColor: 'rgba(255,255,255,0.05)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>{'>'}</div>
          </div>
          <div style={{ display: 'flex', gap: 16 * s, marginLeft: 'auto', alignItems: 'center' }}>
            <div style={{ width: 18 * s, height: 18 * s, border: `${2 * s}px solid #666`, borderRadius: 4 * s }} />
            <div style={{ width: 18 * s, height: 18 * s, border: `${2 * s}px solid #666`, borderRadius: 4 * s }} />
            <div style={{ width: 18 * s, height: 18 * s, border: `${2 * s}px solid #666`, borderRadius: 9 * s }} />
          </div>
        </div>

        {/* Sidebar */}
        <div style={{
          position: 'absolute', left: 0, top: 60 * s, bottom: 0, width: 280 * s,
          backgroundColor: 'rgba(255,255,255,0.02)',
          borderRight: `${1 * s}px solid rgba(255,255,255,0.05)`,
          paddingTop: 30 * s,
          boxSizing: 'border-box'
        }}>
          <SidebarSection title="Favorites" items={["AirDrop", "Recents", "Applications", "Desktop", "Documents", "Downloads"]} s={s} fontFamily={targetFolderTextFontFamily} />
          <SidebarSection title="Locations" items={["iCloud Drive", "Network"]} s={s} fontFamily={targetFolderTextFontFamily} />
          <SidebarSection title="Tags" items={["Important", "Work", "Personal", "Archive", "Project"]} isTags s={s} fontFamily={targetFolderTextFontFamily} />
        </div>

        {/* Folder Grid Area */}
        <div style={{ position: 'absolute', left: 280 * s, top: 60 * s, right: 0, bottom: 0 }}>
          {FOLDER_LABELS.map((label, i) => {
            const isTarget = i === 0; // Target is now the very first folder (YouTube Videos)
            const col = i % 6;
            const row = Math.floor(i / 6);
            
            // Layout Math
            const x = 120 + col * 180;
            const y = 60 + row * 180;

            const hoverScale = getFolderScale(i, t);
            const opacity = isTarget ? 1 : interpolate(t, [160, 200], [1, 0.2], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
            
            const glowOp = isTarget ? interpolate(t, [110, 150, 160, 180], [0, 0.4, 0.4, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }) : 0;
            const folderColor = isTarget
              ? interpolateColors(glowOp, [0, 1], ["#4E5054", primaryColor])
              : "#3A3C40";

            return (
              <div key={i} style={{
                position: 'absolute',
                left: x * s, top: y * s,
                width: 180 * s, height: 180 * s,
                display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
                transform: `scale(${hoverScale})`,
                opacity: opacity
              }}>
                {/* Bloom Behind Target Folder */}
                {isTarget && (
                  <div style={{
                    position: 'absolute',
                    width: 220 * s, height: 220 * s,
                    top: -10 * s,
                    background: `radial-gradient(circle at center, ${primaryColor} 0%, transparent 70%)`,
                    opacity: glowOp,
                    filter: `blur(${30 * s}px)`
                  }} />
                )}
                
                {/* Folder SVG */}
                <svg width={110 * s} height={85 * s} viewBox="0 0 120 90" style={{ zIndex: 2, overflow: 'visible' }}>
                  <defs>
                    <clipPath id={`clip-${i}`}>
                      <path d="M 5 15 C 5 7, 10 2, 18 2 L 40 2 C 45 2, 48 4, 52 8 L 58 15 L 102 15 C 110 15, 115 20, 115 28 L 115 75 C 115 83, 110 88, 102 88 L 18 88 C 10 88, 5 83, 5 75 Z" />
                    </clipPath>
                    <linearGradient id={`shine-${i}`} x1="0" y1="0" x2="1" y2="0">
                      <stop offset="0%" stopColor="transparent" />
                      <stop offset="50%" stopColor="rgba(255,255,255,0.7)" />
                      <stop offset="100%" stopColor="transparent" />
                    </linearGradient>
                  </defs>
                  <path d="M 5 15 C 5 7, 10 2, 18 2 L 40 2 C 45 2, 48 4, 52 8 L 58 15 L 102 15 C 110 15, 115 20, 115 28 L 115 75 C 115 83, 110 88, 102 88 L 18 88 C 10 88, 5 83, 5 75 Z" fill={folderColor} />
                  {isTarget && (
                    <rect
                      x={interpolate(t, [160, 190], [-80, 150], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' })}
                      y="0" width="50" height="90"
                      fill={`url(#shine-${i})`}
                      clipPath={`url(#clip-${i})`}
                      transform="skewX(-20)"
                    />
                  )}
                </svg>
                
                {/* Label */}
                <div style={{
                  marginTop: 16 * s,
                  width: 160 * s,
                  color: isTarget ? interpolateColors(glowOp, [0, 1], ["#9CA3AF", "#FFFFFF"]) : "#9CA3AF",
                  fontSize: 15 * s,
                  fontFamily: targetFolderTextFontFamily,
                  textAlign: 'center',
                  lineHeight: 1.3,
                  zIndex: 2,
                  textShadow: isTarget ? `0 0 ${15 * s * glowOp}px rgba(255,255,255,${glowOp * 0.8})` : 'none',
                  fontWeight: isTarget ? 600 : 400,
                  whiteSpace: 'pre-wrap'
                }}>
                  {isTarget ? targetFolderText : label}
                </div>
              </div>
            );
          })}
        </div>

        {/* Cursor */}
        <div style={{
          position: 'absolute',
          left: (800 + cursor.x) * s,
          top: (450 + cursor.y) * s,
          transform: `scale(${cursorClickScale})`,
          opacity: cursorOpacity,
          zIndex: 100,
          pointerEvents: 'none'
        }}>
          <svg width={24 * s} height={36 * s} viewBox="0 0 24 36" style={{ filter: `drop-shadow(0 ${4 * s}px ${8 * s}px rgba(0,0,0,0.5))` }}>
            <path d="M 2 2 L 18 18 L 11 18 L 16 28 L 12 30 L 7 20 L 2 25 Z" fill="black" stroke="white" strokeWidth="2" strokeLinejoin="round" />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;